#!/usr/bin/env python3
"""
Round 155k (culprits), 3 October 2026. Needs round 154k.

Redraws the seventh basemap as a hand-cut black and white print.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 155k (3 October)\n\nNeeds round 154k. No tiles patch. No app.js?v= bump. The seventh basemap redrawn.\n\n- Owner on 154k: not an engraved pen-and-ink look, too programmatic; wants a\n  natural, hand-crafted black and white Earth First! look. Redrawn as a\n  hand-cut relief print and renamed "Black and white" in the menu (key still\n  "ink"; layers still outline-ink-*). Nothing from any picture is copied.\n- inkDrawSquare redone: sea solid black, a white cut hugging every shore, short\n  wavering cuts out to sea, fewer over the deeps; land white, the side away\n  from the light cut in black strokes that follow the lie of the land (along\n  height lines, swelling into shadow, tapering into light), solid black where\n  too steep to carve; slow wandering fields tied to the ground bend every\n  line and break strokes off (nothing ruled); a print\'s texture (inkGrain).\n  Heights softened first so the grid\'s steps don\'t show as zigzags. North\n  cap black (Arctic sea), south cap white. About 0.25 s a square.\n- Close in: forests a large sheet of scattered hand-drawn conifers, each\n  different (inkPattern pines, 224 px); reed tufts and uneven town dots the\n  same way; sea from zoom 8, lakes and buildings solid black. Layer colours\n  "suited to the basemap": as drawn (black sea, white land).\n- Checked in Chromium with sample heights (zooms 0-2); not seen against the\n  live height tiles. Preview: black_and_white_preview.png in that chat.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round155k: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 154k" not in h.read_text(encoding="utf-8"):
        sys.exit("round155k: round 154k must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round155k: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round155k: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round155k: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
